### Java

```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        Arrays.sort(a);

        long ans = n / 2;  // 处理全等的情况
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && a[j] == a[i]) {
                j++;
            }
            // 以 j 为分界，左边 j 个，右边 n-j 个
            long cur = (long) j * (n - j);
            if (cur > ans) {
                ans = cur;
            }
            i = j;
        }
        System.out.println(ans);
    }
}
```

